186	void drawTexturedQuad(const Vec3& a, const Vec3& b, const Vec3& c, const Vec3& d, float tileU, float tileV) {
187	    const Vec3 n = normalize(cross(b - a, c - a));
188	    glNormal3f(n.x, n.y, n.z);
189	    vertexTextured(a, 0.0f, 0.0f);
190	    vertexTextured(b, tileU, 0.0f);
191	    vertexTextured(c, tileU, tileV);
192	    vertexTextured(d, 0.0f, tileV);
193	}
