222	void drawTexturedCylinder(const Vec3& center,
223	                          float radius,
224	                          float halfHeight,
225	                          int segments,
226	                          GLuint texture,
227	                          const sf::Color& tint) {
228	    bindTexture(texture);
229	    setColor(tint);
230	
231	    glBegin(GL_TRIANGLE_FAN);
232	    glNormal3f(0.0f, 1.0f, 0.0f);
233	    vertexTextured(Vec3{center.x, center.y + halfHeight, center.z}, 0.5f, 0.5f);
234	    for (int i = 0; i <= segments; ++i) {
235	        const float angle = (2.0f * kPi * static_cast<float>(i)) / static_cast<float>(segments);
236	        const float u = 0.5f + std::cos(angle) * 0.5f;
237	        const float v = 0.5f + std::sin(angle) * 0.5f;
238	        vertexTextured(Vec3{center.x + std::cos(angle) * radius, center.y + halfHeight, center.z + std::sin(angle) * radius}, u, v);
239	    }
240	    glEnd();
241	
242	    glBegin(GL_TRIANGLE_FAN);
243	    glNormal3f(0.0f, -1.0f, 0.0f);
244	    vertexTextured(Vec3{center.x, center.y - halfHeight, center.z}, 0.5f, 0.5f);
245	    for (int i = segments; i >= 0; --i) {
246	        const float angle = (2.0f * kPi * static_cast<float>(i)) / static_cast<float>(segments);
247	        const float u = 0.5f + std::cos(angle) * 0.5f;
248	        const float v = 0.5f + std::sin(angle) * 0.5f;
249	        vertexTextured(Vec3{center.x + std::cos(angle) * radius, center.y - halfHeight, center.z + std::sin(angle) * radius}, u, v);
250	    }
251	    glEnd();
252	
253	    glBegin(GL_QUAD_STRIP);
254	    for (int i = 0; i <= segments; ++i) {
255	        const float angle = (2.0f * kPi * static_cast<float>(i)) / static_cast<float>(segments);
256	        const float nx = std::cos(angle);
257	        const float nz = std::sin(angle);
258	        const float u = static_cast<float>(i) / static_cast<float>(segments) * 2.0f;
259	        glNormal3f(nx, 0.0f, nz);
260	        vertexTextured(Vec3{center.x + nx * radius, center.y - halfHeight, center.z + nz * radius}, u, 0.0f);
261	        vertexTextured(Vec3{center.x + nx * radius, center.y + halfHeight, center.z + nz * radius}, u, 1.0f);
262	    }
263	    glEnd();
264	}
