533	void handleMouseLook(sf::RenderWindow& window, GameState& game) {
534	    const sf::Vector2i center(static_cast<int>(window.getSize().x / 2), static_cast<int>(window.getSize().y / 2));
535	    const sf::Vector2i mouse = sf::Mouse::getPosition(window);
536	    const sf::Vector2i delta = mouse - center;
537	
538	    game.player.yawDeg += static_cast<float>(delta.x) * kMouseSensitivity;
539	    game.player.pitchDeg = clampf(game.player.pitchDeg - static_cast<float>(delta.y) * kMouseSensitivity, -kMaxPitchDeg, kMaxPitchDeg);
540	
541	    if (window.hasFocus()) {
542	        sf::Mouse::setPosition(center, window);
543	    }
544	}
