627	void updateEffects(GameState& game, float dt) {
628	    game.damageFlash = std::max(0.0f, game.damageFlash - dt * 1.8f);
629	    game.killFlash = std::max(0.0f, game.killFlash - dt * 2.4f);
630	    for (auto& fx : game.impacts) {
631	        fx.age += dt;
632	    }
633	    game.impacts.erase(
634	        std::remove_if(game.impacts.begin(), game.impacts.end(), [](const ImpactEffect& fx) {
635	            return fx.age >= fx.lifetime;
