639	void updateProjectiles(GameState& game, float dt) {
640	    for (auto& projectile : game.projectiles) {
641	        projectile.pos += projectile.velocity * dt;
642	        projectile.lifetime -= dt;
643	    }
644	
645	    for (auto& projectile : game.projectiles) {
646	        if (projectile.lifetime <= 0.0f) {
647	            continue;
648	        }
649	
650	        if (projectile.fromEnemy) {
651	            const Vec3 playerCenter = game.player.pos + Vec3{0.0f, 2.5f, 0.0f};
652	            if (dot(projectile.pos - playerCenter, projectile.pos - playerCenter) <= 8.0f * 8.0f) {
653	                game.player.health = std::max(0.0f, game.player.health - projectile.damage);
654	                projectile.lifetime = 0.0f;
655	                addImpact(game, playerCenter, sf::Color(255, 90, 90), 3.4f, 0.28f);
656	                game.damageFlash = 0.55f;
657	                if (game.player.health <= 0.0f) {
658	                    game.lost = true;
659	                }
660	            }
661	            continue;
662	        }
663	
664	        for (auto& enemy : game.enemies) {
665	            if (!enemy.alive) {
666	                continue;
667	            }
668	            if (dot(projectile.pos - enemy.pos, projectile.pos - enemy.pos) <= 4.3f * 4.3f) {
669	                enemy.health -= projectile.damage;
670	                projectile.lifetime = 0.0f;
671	                addImpact(game, enemy.pos + Vec3{0.0f, 3.0f, 0.0f}, sf::Color(255, 210, 90), 3.0f, 0.2f);
672	                if (enemy.health <= 0.0f) {
673	                    enemy.alive = false;
674	                    addImpact(game, enemy.pos + Vec3{0.0f, 3.0f, 0.0f}, sf::Color(255, 160, 60), 4.2f, 0.32f);
675	                    ++game.kills;
676	                    game.killFlash = 0.28f;
677	                    if (shouldDropPickup()) {
678	                        spawnPickup(game, enemy.pos);
679	                    }
680	                }
681	                break;
682	            }
683	        }
684	    }
685	
686	    game.projectiles.erase(
687	        std::remove_if(game.projectiles.begin(),
688	                       game.projectiles.end(),
689	                       [](const Projectile& projectile) {
690	                           return projectile.lifetime <= 0.0f ||
691	                                  std::abs(projectile.pos.x) > kArenaHalfSize + 12.0f ||
692	                                  std::abs(projectile.pos.z) > kArenaHalfSize + 12.0f ||
693	                                  projectile.pos.y < -2.0f || projectile.pos.y > 40.0f;
694	                       }),
695	        game.projectiles.end());
696	}
