1013	void renderScene(sf::RenderWindow& window, const GameState& game, const HudAssets& hud) {
1014	    const sf::Vector2u size = window.getSize();
1015	    const float aspect = size.y == 0 ? 1.0f : static_cast<float>(size.x) / static_cast<float>(size.y);
1016	
1017	    glViewport(0, 0, static_cast<GLint>(size.x), static_cast<GLint>(size.y));
1018	    glClearColor(0.57f, 0.74f, 0.96f, 1.0f);
1019	    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
1020	
1021	    glMatrixMode(GL_PROJECTION);
1022	    glLoadIdentity();
1023	    setupPerspective(70.0f, aspect, 0.5f, 500.0f);
1024	
1025	    const Vec3 aim = forwardFromAngles(game.player.yawDeg, game.player.pitchDeg);
1026	    const Vec3 cameraTarget = game.player.pos + Vec3{0.0f, 3.8f, 0.0f};
1027	    const Vec3 eye = cameraTarget - flatForward(game.player.yawDeg) * 15.0f + Vec3{0.0f, 8.0f, 0.0f} - Vec3{0.0f, aim.y * 4.0f, 0.0f};
1028	    const Vec3 target = cameraTarget + aim * 24.0f;
1029	
1030	    glMatrixMode(GL_MODELVIEW);
1031	    glLoadIdentity();
1032	    setupLookAt(eye, target, Vec3{0.0f, 1.0f, 0.0f});
1033	
1034	    const GLfloat lightPos[] = {40.0f, 90.0f, 30.0f, 1.0f};
1035	    glLightfv(GL_LIGHT0, GL_POSITION, lightPos);
1036	
1037	    drawArena(game);
1038	    drawPlayer(game.player);
1039	    for (const auto& enemy : game.enemies) {
1040	        if (enemy.alive) {
1041	            drawEnemy(enemy);
1042	        }
1043	    }
1044	    for (const auto& projectile : game.projectiles) {
1045	        drawProjectile(projectile);
1046	    }
1047	
1048	    drawCrosshair(window);
1049	    window.display();
1050	}
