66	std::string trim(const std::string& s) {
67	    std::size_t begin = 0;
68	    while (begin < s.size() && std::isspace(static_cast<unsigned char>(s[begin])) != 0) {
69	        ++begin;
70	    }
71	
72	    std::size_t end = s.size();
73	    while (end > begin && std::isspace(static_cast<unsigned char>(s[end - 1])) != 0) {
74	        --end;
75	    }
76	
77	    return s.substr(begin, end - begin);
78	}
