80	bool tryParseFloat(const std::string& s, float& out) {
81	    try {
82	        std::size_t idx = 0;
83	        const float value = std::stof(s, &idx);
84	        if (idx != s.size()) {
85	            return false;
86	        }
87	        out = value;
88	        return true;
89	    } catch (...) {
90	        return false;
91	    }
92	}
