94	std::unordered_map<std::string, std::string> parseKeyValueFile(const std::string& path) {
95	    std::unordered_map<std::string, std::string> out;
96	    std::ifstream in(path);
97	    if (!in) {
98	        return out;
99	    }
100	
101	    std::string line;
102	    while (std::getline(in, line)) {
103	        const std::size_t hashPos = line.find('#');
104	        if (hashPos != std::string::npos) {
105	            line = line.substr(0, hashPos);
106	        }
107	
108	        line = trim(line);
109	        if (line.empty()) {
110	            continue;
111	        }
112	
113	        const std::size_t eqPos = line.find('=');
114	        if (eqPos == std::string::npos) {
115	            continue;
116	        }
117	
118	        std::string key = trim(line.substr(0, eqPos));
119	        std::string value = trim(line.substr(eqPos + 1));
120	        if (!key.empty() && !value.empty()) {
121	            out[key] = value;
122	        }
123	    }
124	
125	    return out;
126	}
