128	void applyIfPresent(const std::unordered_map<std::string, std::string>& cfg,
129	                    const std::string& key,
130	                    float& target) {
131	    const auto it = cfg.find(key);
132	    if (it == cfg.end()) {
133	        return;
134	    }
135	
136	    float parsed = 0.0f;
137	    if (!tryParseFloat(it->second, parsed)) {
138	        std::cerr << "Ignoring invalid float for key '" << key << "'\n";
139	        return;
140	    }
141	
142	    target = parsed;
143	}
