188	void sanitizeLoadedConfig() {
189	    kOuterW = std::max(50.0f, kOuterW);
190	    kOuterH = std::max(50.0f, kOuterH);
191	
192	    kInnerW = std::clamp(kInnerW, 10.0f, kOuterW - 20.0f);
193	    kInnerH = std::clamp(kInnerH, 10.0f, kOuterH - 20.0f);
194	
195	    kInnerX = std::clamp(kInnerX, kOuterX + 5.0f, kOuterX + kOuterW - kInnerW - 5.0f);
196	    kInnerY = std::clamp(kInnerY, kOuterY + 5.0f, kOuterY + kOuterH - kInnerH - 5.0f);
197	
198	    const float maxOuterRadius = std::max(0.0f, std::min(kOuterW, kOuterH) * 0.5f - 2.0f);
199	    const float maxInnerRadius = std::max(0.0f, std::min(kInnerW, kInnerH) * 0.5f - 2.0f);
200	    kOuterRadius = std::clamp(kOuterRadius, 0.0f, maxOuterRadius);
201	    kInnerRadius = std::clamp(kInnerRadius, 0.0f, maxInnerRadius);
202	
203	    kLineTop = std::clamp(kLineTop, kOuterY, kOuterY + kOuterH);
204	    kLineBottom = std::clamp(kLineBottom, kOuterY, kOuterY + kOuterH);
205	    if (kLineBottom < kLineTop) {
206	        std::swap(kLineBottom, kLineTop);
207	    }
208	
209	    kLineZoneHalfWidth = std::max(1.0f, kLineZoneHalfWidth);
210	
211	    kWheelBase = std::max(8.0f, kWheelBase);
212	    kMaxSteerDeg = std::clamp(kMaxSteerDeg, 1.0f, 80.0f);
213	    kSteerResponseDegPerSec = std::max(1.0f, kSteerResponseDegPerSec);
214	    kSteerReturnDegPerSec = std::max(1.0f, kSteerReturnDegPerSec);
215	
216	    kMaxForwardSpeed = std::max(1.0f, kMaxForwardSpeed);
217	    kMaxReverseSpeed = std::min(-1.0f, kMaxReverseSpeed);
218	    kAccel = std::max(1.0f, kAccel);
219	    kBrakeAccel = std::max(1.0f, kBrakeAccel);
220	    kDrag = std::max(0.0f, kDrag);
221	}
