239	bool isPointInsideRoundedRect(const sf::Vector2f& p,
240	                              float x,
241	                              float y,
242	                              float w,
243	                              float h,
244	                              float radius) {
245	    const float halfW = w * 0.5f;
246	    const float halfH = h * 0.5f;
247	    const float r = std::clamp(radius, 0.0f, std::max(0.0f, std::min(halfW, halfH) - 0.001f));
248	
249	    const float cx = x + halfW;
250	    const float cy = y + halfH;
251	
252	    const float qx = std::abs(p.x - cx) - (halfW - r);
253	    const float qy = std::abs(p.y - cy) - (halfH - r);
254	
255	    const float mx = std::max(qx, 0.0f);
256	    const float my = std::max(qy, 0.0f);
257	    const float outside = std::sqrt(mx * mx + my * my);
258	    const float inside = std::min(std::max(qx, qy), 0.0f);
259	    return outside + inside <= r;
260	}
