262	std::vector<sf::Vector2f> buildRoundedRectLoop(float x,
263	                                               float y,
264	                                               float w,
265	                                               float h,
266	                                               float radius,
267	                                               int cornerSegments) {
268	    std::vector<sf::Vector2f> pts;
269	    if (w <= 0.0f || h <= 0.0f) {
270	        return pts;
271	    }
272	
273	    const float halfW = w * 0.5f;
274	    const float halfH = h * 0.5f;
275	    const float r = std::clamp(radius, 0.0f, std::max(0.0f, std::min(halfW, halfH) - 0.001f));
276	    const int seg = std::max(2, cornerSegments);
277	
278	    auto appendArc = [&](float cx, float cy, float a0, float a1, bool skipFirst) {
279	        for (int i = 0; i <= seg; ++i) {
280	            if (skipFirst && i == 0) {
281	                continue;
282	            }
283	            const float t = static_cast<float>(i) / static_cast<float>(seg);
284	            const float a = a0 + (a1 - a0) * t;
285	            pts.push_back(sf::Vector2f(cx + std::cos(a) * r, cy + std::sin(a) * r));
286	        }
287	    };
288	
289	    appendArc(x + w - r, y + r, -1.5707963267f, 0.0f, false);
290	    appendArc(x + w - r, y + h - r, 0.0f, 1.5707963267f, true);
291	    appendArc(x + r, y + h - r, 1.5707963267f, 3.1415926535f, true);
292	    appendArc(x + r, y + r, 3.1415926535f, 4.7123889803f, true);
293	
294	    return pts;
295	}
