370	Vec3 cross(const Vec3& a, const Vec3& b) {
371	    return Vec3{
372	        a.y * b.z - a.z * b.y,
373	        a.z * b.x - a.x * b.z,
374	        a.x * b.y - a.y * b.x,
375	    };
376	}
