378	Vec3 normalize(const Vec3& v) {
379	    const float lenSq = dot(v, v);
380	    if (lenSq <= 1e-6f) {
381	        return Vec3{0.0f, 0.0f, 0.0f};
382	    }
383	    const float invLen = 1.0f / std::sqrt(lenSq);
384	    return v * invLen;
385	}
