398	bool isCarOnRoad(const Car& car) {
399	    const sf::Vector2f probes[] = {
400	        sf::Vector2f(0.0f, 0.0f),
401	        sf::Vector2f(18.0f, 0.0f),
402	        sf::Vector2f(-18.0f, 0.0f),
403	        sf::Vector2f(0.0f, 10.0f),
404	        sf::Vector2f(0.0f, -10.0f),
405	    };
406	
407	    for (const auto& probe : probes) {
408	        if (!isPointOnRoad(car.pos + rotateOffset(probe, car.angleDeg))) {
409	            return false;
410	        }
411	    }
412	    return true;
413	}
