440	void updateGame(GameState& game, const InputState& input, float dt) {
441	    if (game.finished) {
442	        return;
443	    }
444	
445	    if (input.accelerate) {
446	        game.car.speed += kAccel * dt;
447	    }
448	    if (input.brake) {
449	        game.car.speed -= kBrakeAccel * dt;
450	    }
451	
452	    if (!input.accelerate && !input.brake) {
453	        if (game.car.speed > 0.0f) {
454	            game.car.speed = std::max(0.0f, game.car.speed - kDrag * dt);
455	        } else {
456	            game.car.speed = std::min(0.0f, game.car.speed + kDrag * dt);
457	        }
458	    }
459	
460	    game.car.speed = std::clamp(game.car.speed, kMaxReverseSpeed, kMaxForwardSpeed);
461	
462	    float targetSteerDeg = 0.0f;
463	    if (input.steerLeft && !input.steerRight) {
464	        targetSteerDeg = -kMaxSteerDeg;
465	    } else if (input.steerRight && !input.steerLeft) {
466	        targetSteerDeg = kMaxSteerDeg;
467	    }
468	
469	    if (std::abs(targetSteerDeg) > 0.0f) {
470	        const float steerStep = kSteerResponseDegPerSec * dt;
471	        if (game.car.steerDeg < targetSteerDeg) {
472	            game.car.steerDeg = std::min(targetSteerDeg, game.car.steerDeg + steerStep);
473	        } else if (game.car.steerDeg > targetSteerDeg) {
474	            game.car.steerDeg = std::max(targetSteerDeg, game.car.steerDeg - steerStep);
475	        }
476	    } else {
477	        const float returnStep = kSteerReturnDegPerSec * dt;
478	        if (game.car.steerDeg > 0.0f) {
479	            game.car.steerDeg = std::max(0.0f, game.car.steerDeg - returnStep);
480	        } else if (game.car.steerDeg < 0.0f) {
481	            game.car.steerDeg = std::min(0.0f, game.car.steerDeg + returnStep);
482	        }
483	    }
484	
485	    if (std::abs(game.car.speed) > 0.1f && std::abs(game.car.steerDeg) > 0.01f) {
486	        const float steerRad = degToRad(game.car.steerDeg);
487	        const float angularVelocity = (game.car.speed / kWheelBase) * std::tan(steerRad);
488	        game.car.angleDeg += radToDeg(angularVelocity * dt);
489	    }
490	
491	    const float rad = degToRad(game.car.angleDeg);
492	    const sf::Vector2f dir(std::cos(rad), std::sin(rad));
493	    game.car.pos += dir * game.car.speed * dt;
494	
495	    if (!isCarOnRoad(game.car)) {
496	        resetCar(game.car);
497	        game.checkpointPassed = false;
498	        game.wasInCheckpointZone = false;
499	        game.wasInStartZone = false;
500	        return;
501	    }
502	
503	    const bool isInCheckpointZone = isInLineZone(game.car.pos, kCheckpointX);
504	    const bool isInStartZone = isInLineZone(game.car.pos, kStartLineX);
505	
506	    if (isInCheckpointZone && !game.wasInCheckpointZone) {
507	        game.checkpointPassed = true;
508	    }
509	
510	    if (isInStartZone && !game.wasInStartZone && game.checkpointPassed) {
511	        ++game.lapCount;
512	        game.checkpointPassed = false;
513	        if (game.lapCount >= kTargetLaps) {
514	            game.finished = true;
515	            game.car.speed = 0.0f;
516	        }
517	    }
518	
519	    game.wasInCheckpointZone = isInCheckpointZone;
520	    game.wasInStartZone = isInStartZone;
521	}
