559	sf::Vector2f projectWorldPoint(const sf::Vector2f& p, const CameraState& camera) {
560	    const float angle = degToRad(camera.angleDeg);
561	    const sf::Vector2f rel = p - camera.pos;
562	
563	    const float forward = std::max(camera.minDepth, rel.x * std::cos(angle) + rel.y * std::sin(angle));
564	    const float lateral = -rel.x * std::sin(angle) + rel.y * std::cos(angle);
565	
566	    const float x = kWindowWidth * 0.5f + (lateral * camera.focalLength) / forward;
567	    const float y = camera.horizonY + camera.depthScale / forward;
568	    return sf::Vector2f(x, y);
569	}
