584	void setupPerspective(float fovDeg, float aspect, float nearPlane, float farPlane) {
585	    const float fovRad = degToRad(fovDeg);
586	    const float top = nearPlane * std::tan(fovRad * 0.5f);
587	    const float right = top * aspect;
588	    glFrustum(-right, right, -top, top, nearPlane, farPlane);
