591	void setupLookAt(const Vec3& eye, const Vec3& center, const Vec3& up) {
592	    const Vec3 f = normalize(center - eye);
593	    const Vec3 s = normalize(cross(f, up));
594	    const Vec3 u = cross(s, f);
595	
596	    // OpenGL expects column-major order; translation lives in the 4th column.
597	    const std::array<float, 16> matrix = {
598	        s.x, u.x, -f.x, 0.0f,
599	        s.y, u.y, -f.y, 0.0f,
600	        s.z, u.z, -f.z, 0.0f,
601	        -dot(s, eye), -dot(u, eye), dot(f, eye), 1.0f,
602	    };
603	
604	    glLoadMatrixf(matrix.data());
605	}
