611	void drawQuad3D(const Vec3& a, const Vec3& b, const Vec3& c, const Vec3& d, const sf::Color& color) {
612	    const Vec3 normal = normalize(cross(b - a, c - a));
613	    setGlColor(color);
614	    glBegin(GL_QUADS);
615	    glNormal3f(normal.x, normal.y, normal.z);
616	    glVertex3f(a.x, a.y, a.z);
617	    glVertex3f(b.x, b.y, b.z);
618	    glVertex3f(c.x, c.y, c.z);
619	    glVertex3f(d.x, d.y, d.z);
620	    glEnd();
621	}
