636	    const Vec3 rtb{center.x + halfX, center.y + halfY, center.z + halfZ};
637	    const Vec3 ltb{center.x - halfX, center.y + halfY, center.z + halfZ};
638	
639	    drawQuad3D(ltf, rtf, rtb, ltb, topColor);
640	    drawQuad3D(lbf, rbf, rtf, ltf, sideColor);
641	    drawQuad3D(rbf, rbb, rtb, rtf, sideColor);
642	    drawQuad3D(rbb, lbb, ltb, rtb, sideColor);
