689	void drawRoadGuides3D() {
690	    constexpr float guideY = 0.18f;
691	    constexpr float halfW = 1.8f;
692	    const sf::Color guideColor(255, 255, 255);
693	
694	    const auto outerLoop = buildRoundedRectLoop(kOuterX, kOuterY, kOuterW, kOuterH, kOuterRadius, 18);
695	    const auto innerLoop = buildRoundedRectLoop(kInnerX, kInnerY, kInnerW, kInnerH, kInnerRadius, 18);
696	    if (outerLoop.size() >= 3 && innerLoop.size() >= 3) {
697	        const std::size_t n = std::min(outerLoop.size(), innerLoop.size());
698	        for (std::size_t i = 0; i < n; ++i) {
699	            if ((i % 2) != 0) {
700	                continue;
701	            }
702	
703	            const std::size_t j = (i + 1) % n;
704	            const sf::Vector2f a = (outerLoop[i] + innerLoop[i]) * 0.5f;
705	            const sf::Vector2f b = (outerLoop[j] + innerLoop[j]) * 0.5f;
706	            const sf::Vector2f d = b - a;
707	            const float len = std::sqrt(d.x * d.x + d.y * d.y);
708	            if (len < 1e-3f) {
709	                continue;
710	            }
711	
712	            const sf::Vector2f nrm(-d.y / len * halfW, d.x / len * halfW);
713	            drawQuad3D(toWorld3D(a - nrm, guideY),
714	                       toWorld3D(b - nrm, guideY),
715	                       toWorld3D(b + nrm, guideY),
716	                       toWorld3D(a + nrm, guideY),
717	                       guideColor);
718	        }
719	    }
720	
721	    constexpr float lineY = 0.2f;
722	    drawQuad3D(toWorld3D(sf::Vector2f(kStartLineX - 4.0f, kLineTop), lineY),
723	               toWorld3D(sf::Vector2f(kStartLineX + 4.0f, kLineTop), lineY),
724	               toWorld3D(sf::Vector2f(kStartLineX + 4.0f, kLineBottom), lineY),
725	               toWorld3D(sf::Vector2f(kStartLineX - 4.0f, kLineBottom), lineY),
726	               sf::Color::White);
727	
728	    drawQuad3D(toWorld3D(sf::Vector2f(kCheckpointX - 3.0f, kLineTop), lineY),
729	               toWorld3D(sf::Vector2f(kCheckpointX + 3.0f, kLineTop), lineY),
730	               toWorld3D(sf::Vector2f(kCheckpointX + 3.0f, kLineBottom), lineY),
731	               toWorld3D(sf::Vector2f(kCheckpointX - 3.0f, kLineBottom), lineY),
732	               sf::Color(255, 216, 60));
733	}
