741	    const auto innerLoop = buildRoundedRectLoop(kInnerX, kInnerY, kInnerW, kInnerH, kInnerRadius, 18);
742	
743	    auto drawWallLoop = [&](const std::vector<sf::Vector2f>& loop, bool reverse) {
744	        if (loop.size() < 3) {
745	            return;
746	        }
747	        for (std::size_t i = 0; i < loop.size(); ++i) {
748	            const std::size_t j = (i + 1) % loop.size();
749	            sf::Vector2f a = loop[i];
750	            sf::Vector2f b = loop[j];
751	            if (reverse) {
752	                std::swap(a, b);
753	            }
754	            drawQuad3D(toWorld3D(a, wallBottomY),
755	                       toWorld3D(b, wallBottomY),
756	                       toWorld3D(b, wallTopY),
757	                       toWorld3D(a, wallTopY),
758	                       wallSide);
759	        }
760	    };
761	
762	    drawWallLoop(outerLoop, false);
763	    drawWallLoop(innerLoop, true);
764	}
