836	void renderTrue3D(sf::RenderWindow& window,
837	                  const GameState& game,
838	                  int cameraPreset,
839	                  bool unlitMode,
840	                  bool wireframeMode,
841	                  bool rawDebugView) {
842	    const sf::Vector2u size = window.getSize();
843	    const float aspect = (size.y == 0) ? 1.0f : static_cast<float>(size.x) / static_cast<float>(size.y);
844	
845	    glViewport(0, 0, static_cast<GLint>(size.x), static_cast<GLint>(size.y));
846	    glClearColor(0.47f, 0.70f, 0.95f, 1.0f);
847	    glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
