69	// Try a few likely font paths so the game runs on stock Linux and Windows
70	// without bundling a font. Returns the first existing path or empty.
71	fs::path findSystemFont() {
72	    const char* candidates[] = {
73	        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
74	        "/usr/share/fonts/dejavu/DejaVuSans.ttf",
75	        "/usr/share/fonts/TTF/DejaVuSans.ttf",
76	        "/Library/Fonts/Arial.ttf",
77	        "C:/Windows/Fonts/segoeui.ttf",
78	        "C:/Windows/Fonts/arial.ttf",
79	    };
80	    for (const char* c : candidates) {
81	        if (fs::exists(c)) return fs::path(c);
82	    }
83	    return {};
84	}
