105	int main() {
106	    // Resolve project-relative paths so the binary can be launched from build/.
107	    fs::path exeDir = fs::current_path();
108	    fs::path projectRoot = exeDir;
109	    for (int i = 0; i < 4; ++i) {
110	        if (fs::exists(projectRoot / "config" / "llm.cfg")) break;
111	        if (projectRoot.has_parent_path()) projectRoot = projectRoot.parent_path();
112	    }
113	    const fs::path configDir = projectRoot / "config";
114	    const fs::path personasDir = projectRoot / "personas";
115	
116	    llm_npc::LlmConfig llmConfig = loadLlmConfig(configDir);
117	    std::cerr << "[llm_npc] using model=" << llmConfig.model
118	              << " host=" << llmConfig.host << ":" << llmConfig.port << "\n";
119	
120	    sf::RenderWindow window(sf::VideoMode(1280, 720), "Companion — LLM NPC demo");
121	    window.setFramerateLimit(60);
122	
123	    sf::Font font;
124	    fs::path fontPath = findSystemFont();
125	    if (fontPath.empty() || !font.loadFromFile(fontPath.string())) {
126	        std::cerr << "[llm_npc] no system font found; UI will not render text.\n";
127	        return 1;
128	    }
129	
130	    llm_npc::LlmClient client(llmConfig);
131	    llm_npc::Npc companion(buildCompanion(personasDir), client);
132	    llm_npc::DialogUI ui(font);
133	
134	    ui.appendLine({llm_npc::TranscriptLine::Kind::System, "",
135	                   "Press Enter to send. Esc to quit. Talk to " + companion.persona().name + "."});
136	
137	    while (window.isOpen()) {
138	        sf::Event event;
139	        while (window.pollEvent(event)) {
140	            if (event.type == sf::Event::Closed) window.close();
141	            if (event.type == sf::Event::KeyPressed && event.key.code == sf::Keyboard::Escape) {
142	                window.close();
143	            }
144	
145	            std::string submitted = ui.handleEvent(event);
146	            if (!submitted.empty() && !companion.waiting()) {
147	                ui.appendLine({llm_npc::TranscriptLine::Kind::Player, "You", submitted});
148	                companion.ask(submitted);
149	                ui.setThinking(true, companion.persona().name);
150	                ui.setInputEnabled(false);
151	            }
152	        }
153	
154	        for (const auto& reply : client.drainReplies()) {
155	            auto text = companion.onReplyArrived(reply);
156	            if (text) {
157	                ui.appendLine({llm_npc::TranscriptLine::Kind::Npc, companion.persona().name, *text});
158	            } else if (!reply.ok) {
159	                ui.appendLine({llm_npc::TranscriptLine::Kind::System, "",
160	                               "[" + companion.persona().name + " seems distracted: " +
161	                                   reply.errorMessage + "]"});
162	            }
163	            ui.setThinking(false);
164	            ui.setInputEnabled(true);
165	        }
166	
167	        window.clear(sf::Color(18, 18, 22));
168	        ui.render(window);
169	        window.display();
170	    }
171	    return 0;
172	}
